#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    scanf("%lld", &n);
    // The total can reach about 1e19, beyond signed 64-bit: use unsigned.
    unsigned long long total = 0;
    for (long long i = 0; i < n; i++) {
        unsigned long long b;
        scanf("%llu", &b);
        total += b * (unsigned long long)(2 * (n - i) + 1);
    }
    printf("%llu\n", total);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        long n = Long.parseLong(st.nextToken());
        // The total can reach about 1e19, beyond signed 64-bit: wrap and print as unsigned.
        long total = 0;
        for (long i = 0; i < n; i++) total += Long.parseLong(st.nextToken()) * (2 * (n - i) + 1);
        System.out.println(Long.toUnsignedString(total));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() uint64 { sc.Scan(); v, _ := strconv.ParseUint(sc.Text(), 10, 64); return v }
	n := next()
	// The total can reach about 1e19, beyond signed 64-bit: use unsigned.
	var total uint64
	for i := uint64(0); i < n; i++ {
		total += next() * (2*(n-i) + 1)
	}
	fmt.Println(total)
}
